namespace Convenciones.Documents;

/// <summary>
/// Stores document bytes under a private root directory, outside any web-served path.
/// </summary>
/// <remarks>
/// <para>
/// A development and test substitute, not the production path: Supabase Storage is T18 and needs an
/// approved project. It is honest about that in <c>docs/tasks/task-04-document-upload.md</c> rather than
/// letting a local directory be mistaken for a managed private bucket.
/// </para>
/// <para>
/// Keys are generated by the server and validated before use, so a key can never escape the root:
/// <c>..</c>, a rooted path, or a separator at the start would be a path traversal.
/// </para>
/// </remarks>
public sealed class LocalDocumentStorage : IDocumentStorage
{
    private readonly string _root;

    public LocalDocumentStorage(string root)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(root);

        _root = Path.GetFullPath(root);
        Directory.CreateDirectory(_root);
    }

    public async Task SaveAsync(string key, Stream content, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(content);

        var path = Resolve(key);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);

        await using var target = new FileStream(
            path, FileMode.Create, FileAccess.Write, FileShare.None, bufferSize: 81920, useAsync: true);

        await content.CopyToAsync(target, cancellationToken).ConfigureAwait(false);
    }

    public Task<Stream?> OpenReadAsync(string key, CancellationToken cancellationToken)
    {
        var path = Resolve(key);

        if (!File.Exists(path))
        {
            return Task.FromResult<Stream?>(null);
        }

        Stream stream = new FileStream(
            path, FileMode.Open, FileAccess.Read, FileShare.Read, bufferSize: 81920, useAsync: true);

        return Task.FromResult<Stream?>(stream);
    }

    public Task<bool> ExistsAsync(string key, CancellationToken cancellationToken) =>
        Task.FromResult(File.Exists(Resolve(key)));

    public Task DeleteAsync(string key, CancellationToken cancellationToken)
    {
        var path = Resolve(key);

        if (File.Exists(path))
        {
            File.Delete(path);
        }

        return Task.CompletedTask;
    }

    private string Resolve(string key)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(key);

        if (key.Contains("..", StringComparison.Ordinal)
            || Path.IsPathRooted(key)
            || key.Contains('\\', StringComparison.Ordinal))
        {
            throw new ArgumentException($"Unsafe storage key: '{key}'.", nameof(key));
        }

        var path = Path.GetFullPath(Path.Combine(_root, key));

        // Belt and braces: even a key that passed the checks above must resolve inside the root.
        if (!path.StartsWith(_root + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase))
        {
            throw new ArgumentException($"Storage key escapes the root: '{key}'.", nameof(key));
        }

        return path;
    }
}
